class Solution {
public:
    vector<int> prisonAfterNDays(vector<int>& cells, int n) {
        unordered_map<int, int> seen;
        int state = 0;
        for (int i = 0; i < 8; i++) {
            if (cells[i]) state |= (1 << i);
        }
        int day = 0;
        while (day < n) {
            if (seen.count(state)) {
                int cycle = day - seen[state];
                int remaining = n - day;
                day = n - remaining % cycle;
                seen.clear();
                if (day >= n) break;
            }
            seen[state] = day;
            int next = 0;
            for (int i = 1; i < 7; i++) {
                if (((state >> (i - 1)) & 1) == ((state >> (i + 1)) & 1)) {
                    next |= (1 << i);
                }
            }
            state = next;
            day++;
        }
        vector<int> result(8, 0);
        for (int i = 0; i < 8; i++) {
            if (state & (1 << i)) result[i] = 1;
        }
        return result;
    }
};
